#[test]
fn syev_f64_control() {
    let mut v_a: Vec<f64> = (0..(N * N))
        .map(|i| if i % (N + 1) == 0 { 1.0 } else { 0.0 })
        .collect();
    let mut v_w: Vec<f64> = (0..(N)).map(|_| 1.0).collect();
    let r = syev::<f64>(
        Compute::ValuesAndVectors,
        Uplo::Upper,
        N,
        &mut v_a,
        &mut v_w,
    );
    assert!(r.is_ok(), "syev_f64_control: {:?}", r.as_ref().err());
}
